mapper.update:
UPDATE sys_media_task
SET status = #{status},
    error_log = #{errorLog},

    meta_info = #{metaInfo, typeHandler=com.baomidou.mybatisplus.extension.handlers.JacksonTypeHandler},

    updated_at = CURRENT_TIMESTAMP
WHERE task_id = #{taskId}
  AND status = 'RUNNING'
  AND worker_node = #{workerNode}
  AND claim_version = #{claimVersion}

UPDATE sys_media_task
SET updated_at = CURRENT_TIMESTAMP
WHERE task_id = #{taskId}
  AND status = 'RUNNING'
  AND worker_node = #{workerNode}
  AND claim_version = #{claimVersion}

UPDATE sys_media_task
SET status = 'FAILED',
    worker_node = NULL,
    next_retry_at = NULL,
    error_log = #{errorLog},
    updated_at = CURRENT_TIMESTAMP
WHERE task_id = #{taskId}
  AND status = 'RUNNING'
  AND worker_node = #{workerNode}
  AND claim_version = #{claimVersion}
